BEGIN IMMEDIATE;
CREATE TABLE accounts (
    id INTEGER PRIMARY KEY,
    username TEXT NOT NULL UNIQUE COLLATE NOCASE,
    password_hash TEXT NOT NULL,
    created_at INTEGER NOT NULL
);
CREATE TABLE sessions (
    token_hash TEXT PRIMARY KEY,
    account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    expires_at INTEGER NOT NULL
);
CREATE INDEX sessions_account ON sessions(account_id);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE characters (
    id INTEGER PRIMARY KEY,
    account_id INTEGER NOT NULL UNIQUE REFERENCES accounts(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    name_key TEXT NOT NULL UNIQUE,
    archetype TEXT NOT NULL CHECK (archetype IN ('warrior','mage','archer')),
    level INTEGER NOT NULL DEFAULT 1 CHECK (level >= 1),
    gold INTEGER NOT NULL DEFAULT 0 CHECK (gold BETWEEN 0 AND 2147483647),
    diamonds INTEGER NOT NULL DEFAULT 0 CHECK (diamonds BETWEEN 0 AND 2147483647),
    created_at INTEGER NOT NULL
);
CREATE TABLE diamond_ledger (
    id INTEGER PRIMARY KEY,
    character_id INTEGER NOT NULL REFERENCES characters(id),
    before_amount INTEGER NOT NULL CHECK (before_amount BETWEEN 0 AND 2147483647),
    after_amount INTEGER NOT NULL CHECK (after_amount BETWEEN 0 AND 2147483647),
    reason TEXT NOT NULL,
    created_at INTEGER NOT NULL
);
PRAGMA user_version = 1;
COMMIT;
